import json
def f(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # segment: contiguous non-zero run in row 0
    cells=[(0,c,g[0][c]) for c in range(w) if g[0][c]]
    # find singletons: nonzero cells not in segment
    singles={}
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v and (r,c) not in [(0,c2[1]) for c2 in cells]:
                singles[v]=(r,c)
    for r,c,v in cells:
        out[0][c]=v
        if v in singles:
            sr,sc=singles[v]
            for rr in range(0,sr+1): out[rr][c]=v
            for cc in range(min(c,sc),max(c,sc)+1): out[sr][cc]=v
        else:
            for rr in range(h): out[rr][c]=v
    return out

